Body:
without basic path ,  I use  sub_filter to  handle this
```yml
apiVersion: "networking.k8s.io/v1"
kind: "Ingress"
metadata:
  name: "opencode"
  annotations:
    nginx.ingress.kubernetes.io/ssl-redirect: "false"
    nginx.ingress.kubernetes.io/configuration-snippet: |
      rewrite ^/opencode(/|$)(.*)$ /$2 break;
      proxy_set_header Accept-Encoding "";
      sub_filter_once off;
      sub_filter_types text/html application/javascript text/javascript text/css;
      sub_filter ' href="/'       ' href="/opencode/';
      sub_filter ' src="/'        ' src="/opencode/';
      sub_filter ' content="/'    ' content="/opencode/';
      sub_filter ' srcset="/'     ' srcset="/opencode/';
      sub_filter ' manifest="/'   ' manifest="/opencode/';
      sub_filter 'url(/'           'url(/opencode/';
      sub_filter 'url("/'         'url("/opencode/';
      sub_filter 'url:"/'         'url:"/opencode/';
      sub_filter '="/assets/'     '="/opencode/assets/';
      sub_filter '"assets/'       '"/opencode/assets/';
      sub_filter '/assets/'        '/opencode/assets/';
  labels:
    app.kubernetes.io/part-of: "agent"
    app.kubernetes.io/component: "skill"
    app.kubernetes.io/instance: "opencode"
spec:
  ingressClassName: "nginx"
  rules:
    - http:
        paths:
          - backend:
              service:
                name: "opencode"
                port:
                  number: 5000
            path: "/opencode(/|$)(.*)"
            pathType: "ImplementationSpecific"
```
